// ========================================================
// 📋 解析配置并生成RSS源列表
// ========================================================

const configData = $input.all();
if (!configData || configData.length === 0) {
  throw new Error('⚠️ 未收到配置数据');
}

const items = configData[0].json?.data?.items || [];
const config = {};

function getText(val) {
  if (!val) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val) && val[0]?.text) return String(val[0].text).trim();
  if (typeof val === 'object' && val.text) return String(val.text).trim();
  return '';
}

// 解析配置项
for (const rec of items) {
  const f = rec.fields || {};
  const key = getText(f.config_key);
  const value = getText(f.config_value);
  if (key) config[key] = value;
}

console.log('📋 配置加载成功:', JSON.stringify(config, null, 2));

// 解析启用的RSS源（用 | 分隔）
const rssFeeds = (config.rss_feeds || '')
  .split('|')
  .map(s => s.trim())
  .filter(Boolean);

// 解析关键词（用 | 分隔）
const keywords = (config.keywords || '')
  .split('|')
  .map(s => s.trim())
  .filter(Boolean);

if (rssFeeds.length === 0) {
  throw new Error('❌ 配置中未找到 rss_feeds');
}

console.log(`✅ 已加载 ${rssFeeds.length} 个RSS源`);
console.log(`✅ 已加载 ${keywords.length} 个关键词`);

// 为每个RSS源生成一个输出项
const outputs = rssFeeds.map(url => ({
  json: {
    rss_url: url,
    keywords: keywords,
    days_back: parseInt(config.days_back) || 7,
    max_items: parseInt(config.max_items_per_source) || 20,
    ai_model: config.ai_model || 'gpt-4o-mini',
    ai_prompt_summary: config.ai_prompt_summary || '请用50字以内总结这条物流新闻的核心要点',
    ai_prompt_tiktok: config.ai_prompt_tiktok || '请将这条物流新闻改写成60秒TikTok新闻播报脚本，使用滚动字幕形式，语言简洁有力'
  }
}));

return outputs;

// ========================================================
// 📰 提取RSS新闻条目并过滤
// ========================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json?.data || item.json || {};
  const rss = data.rss || data;
  const channel = rss.channel || rss;
  const entries = Array.isArray(channel.item) ? channel.item : [channel.item];

  const keywords = item.json.keywords || [];
  const daysBack = item.json.days_back || 7;
  const maxItems = item.json.max_items || 20;

  const now = Date.now();
  const timeLimit = daysBack * 24 * 60 * 60 * 1000;

  let count = 0;

  for (const entry of entries) {
    if (!entry || count >= maxItems) break;

    const title = entry.title || '';
    const description = entry.description || entry.summary || '';
    const link = entry.link || entry.guid || '';
    const pubDate = entry.pubDate || entry.published || '';

    // 时间过滤
    let publishTime = new Date(pubDate).getTime();
    if (isNaN(publishTime)) publishTime = now; // 无法解析时间则视为最新

    if (now - publishTime > timeLimit) {
      continue; // 超过时间范围
    }

    // 关键词过滤（标题或描述包含任一关键词）
    const content = (title + ' ' + description).toLowerCase();
    const matched = keywords.length === 0 || keywords.some(kw => 
      content.includes(kw.toLowerCase())
    );

    if (!matched) continue;

    // 提取数据
    results.push({
      json: {
        title: String(title).substring(0, 500),
        description: String(description).substring(0, 2000),
        link: String(link),
        pub_date: pubDate,
        source: channel.title || 'Unknown',
        status: 'pending_ai',
        keywords: item.json.keywords,
        ai_model: item.json.ai_model,
        ai_prompt_summary: item.json.ai_prompt_summary,
        ai_prompt_tiktok: item.json.ai_prompt_tiktok
      }
    });

    count++;
  }
}

console.log(`✅ 提取了 ${results.length} 条符合条件的新闻`);

return results;

// ========================================================
// 🤖 调用AI生成摘要和TikTok脚本
// ========================================================

const data = $json;

const newsTitle = data.title || '';
const newsDesc = data.description || '';
const fullContent = `标题：${newsTitle}\n\n内容：${newsDesc}`;

// 这里需要替换成真实的AI API调用
// 示例使用占位符，实际应该用 OpenAI/Claude 等节点

const summary = `[AI摘要] ${newsTitle.substring(0, 50)}...`;
const tiktokScript = `📢 物流快讯\n\n${newsTitle}\n\n[60秒新闻脚本待AI生成]`;

return {
  json: {
    ...data,
    ai_summary: summary,
    tiktok_script: tiktokScript,
    status: 'ready_for_production'
  }
};

// ========================================================
// 🔥 计算新闻热度评分
// ========================================================

const data = $json;

// 时效性评分（0-40分）
const pubDate = new Date(data.pub_date).getTime();
const now = Date.now();
const hoursAgo = (now - pubDate) / (1000 * 60 * 60);
let timeScore = 0;
if (hoursAgo < 24) timeScore = 40;
else if (hoursAgo < 48) timeScore = 30;
else if (hoursAgo < 72) timeScore = 20;
else timeScore = 10;

// 关键词匹配度（0-30分）
const keywords = data.keywords || [];
const content = (data.title + ' ' + data.description).toLowerCase();
const matchCount = keywords.filter(kw => content.includes(kw.toLowerCase())).length;
const keywordScore = Math.min(matchCount * 10, 30);

// 内容丰富度（0-30分）
const contentLength = (data.title + data.description).length;
let richScore = 0;
if (contentLength > 500) richScore = 30;
else if (contentLength > 300) richScore = 20;
else richScore = 10;

// 总分
const hotnessScore = timeScore + keywordScore + richScore;

// 热度等级
let hotLevel = 'Low';
if (hotnessScore >= 80) hotLevel = '🔥极热';
else if (hotnessScore >= 60) hotLevel = 'High';
else if (hotnessScore >= 40) hotLevel = 'Medium';

return {
  json: {
    ...data,
    hotness_score: hotnessScore,
    hot_level: hotLevel
  }
};

// ========================================================
// 📦 构建飞书写入Body
// ========================================================

const items = $input.all();

function sanitize(s) {
  if (s == null) return '';
  s = String(s);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ');
  s = s.replace(/\r\n?/g, '\n');
  return s.trim();
}

const records = items.map(it => {
  const j = it.json || {};
  return {
    fields: {
      "title": sanitize(j.title),
      "description": sanitize(j.description),
      "link": sanitize(j.link),
      "source": sanitize(j.source),
      "pub_date": sanitize(j.pub_date),
      "ai_summary": sanitize(j.ai_summary),
      "tiktok_script": sanitize(j.tiktok_script),
      "hotness_score": sanitize(j.hotness_score),
      "hot_level": sanitize(j.hot_level),
      "status": sanitize(j.status || 'ready_for_production')
    }
  };
});

// 分片（每次最多100条）
function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

const chunks = chunk(records, 100);

console.log(`📦 生成 ${chunks.length} 个批次，共 ${records.length} 条`);

return chunks.map(part => ({
  json: {
    body: JSON.stringify({ records: part })
  }
}));
